output_text:
[
  {
    "id": "must_take_entrance_cart",
    "text": "A shopper must take the entrance cart before doing the trip.",
    "abstraction": {
      "state_properties": {
        "entrance_cart_station": {
          "and": [
            "at(1,5)",
            "cartAt(1,5)"
          ]
        }
      },
      "events": {
        "take_entrance_cart": {
          "pre": {
            "and": [
              "entrance_cart_station",
              "PICKUP_CART"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "take_entrance_cart"
    }
  },
  {
    "id": "items_only_with_cart",
    "text": "Items may only be picked up while the shopper has a cart.",
    "abstraction": {
      "state_properties": {
        "without_cart": {
          "not": "hasCart"
        }
      },
      "events": {
        "item_pickup": {
          "pre": "PICKUP_ITEM",
          "post": null
        },
        "cartless_item_pickup": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              "without_cart"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "cartless_item_pickup"
    }
  },
  {
    "id": "no_hand_carrying",
    "text": "Shoppers must not carry groceries by hand.",
    "abstraction": {
      "state_properties": {
        "carrying_by_hand": "handFull",
        "cart_transport": "hasCart"
      },
      "events": {
        "become_hand_full": {
          "pre": {
            "not": "handFull"
          },
          "post": "handFull"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "carrying_by_hand"
    }
  },
  {
    "id": "return_cart_to_nw_corral",
    "text": "Before leaving, the shopper must park the cart at the northwest cart return.",
    "abstraction": {
      "state_properties": {
        "nw_cart_return_cell": "at(0,1)",
        "cart_parked_at_nw_return": "cartAt(0,1)"
      },
      "events": {
        "return_cart_to_nw_corral": {
          "pre": {
            "and": [
              "nw_cart_return_cell",
              "hasCart",
              "LEAVE_CART"
            ]
          },
          "post": "cart_parked_at_nw_return"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "return_cart_to_nw_corral"
    }
  },
  {
    "id": "no_abandon_cart_elsewhere",
    "text": "A shopper must not leave the cart anywhere except the northwest cart return.",
    "abstraction": {
      "state_properties": {
        "nw_cart_return_cell": "at(0,1)",
        "not_at_nw_return": {
          "not": "nw_cart_return_cell"
        }
      },
      "events": {
        "leave_cart": {
          "pre": "LEAVE_CART",
          "post": null
        },
        "leave_cart_wrong_place": {
          "pre": {
            "and": [
              "LEAVE_CART",
              "not_at_nw_return"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "leave_cart_wrong_place"
    }
  },
  {
    "id": "exit_only_after_cart_returned",
    "text": "A shopper may exit only after the cart is parked at the northwest return.",
    "abstraction": {
      "state_properties": {
        "cart_parked_at_nw_return": "cartAt(0,1)",
        "cart_not_returned": {
          "not": "cart_parked_at_nw_return"
        }
      },
      "events": {
        "exit_with_cart_unreturned": {
          "pre": {
            "and": [
              "EXIT",
              "cart_not_returned"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "exit_with_cart_unreturned"
    }
  },
  {
    "id": "no_exit_while_pushing_cart",
    "text": "A shopper must not leave the store while still holding or pushing the cart.",
    "abstraction": {
      "state_properties": {
        "pushing_cart": "hasCart",
        "east_exit_cell": "at(9,5)"
      },
      "events": {
        "cart_exit": {
          "pre": {
            "and": [
              "EXIT",
              "pushing_cart"
            ]
          },
          "post": null
        },
        "proper_cart_free_exit": {
          "pre": {
            "and": [
              "EXIT",
              "east_exit_cell",
              {
                "not": "pushing_cart"
              }
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "cart_exit"
    }
  },
  {
    "id": "after_item_return_cart",
    "text": "After picking up any required item, the shopper is obliged eventually to return the cart to the northwest cart return.",
    "abstraction": {
      "state_properties": {
        "nw_cart_return_cell": "at(0,1)",
        "cart_parked_at_nw_return": "cartAt(0,1)"
      },
      "events": {
        "collect_item": {
          "pre": "PICKUP_ITEM",
          "post": null
        },
        "return_cart_to_nw_corral": {
          "pre": {
            "and": [
              "nw_cart_return_cell",
              "hasCart",
              "LEAVE_CART"
            ]
          },
          "post": "cart_parked_at_nw_return"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "collect_item",
      "discharge": "return_cart_to_nw_corral"
    }
  }
]
